(window.TKA_DATA=window.TKA_DATA||{})["bank-ekonomi"]={"id":"ekonomi","name":"Ekonomi","count":118,"items":[{"id":"0.0.0","topic":"Konsep Dasar Ekonomi","sub":"1.1 Hakikat, Pembagian & Prinsip Ilmu Ekonomi","kind":"pg","stem":"Manakah di antara topik berikut yang merupakan bahasan Teori Ekonomi Mikro?","options":["Kebijakan pengurangan pengangguran terbuka melalui proyek padat karya","Pengaruh kenaikan suku bunga BI terhadap laju inflasi nasional","Penentuan harga keseimbangan beras di Pasar Induk Kramat Jati","Dampak defisit neraca perdagangan terhadap cadangan devisa"],"key":[2],"why":"Ekonomi mikro menganalisis bagian kecil/spesifik seperti harga satu komoditas di pasar tertentu, perilaku konsumen, dan produsen.","src":"kuis"},{"id":"0.0.1","topic":"Konsep Dasar Ekonomi","sub":"1.1 Hakikat, Pembagian & Prinsip Ilmu Ekonomi","kind":"pg","stem":"Pernyataan 'Pemerintah seharusnya membebaskan pajak penghasilan bagi pekerja berupah minimum agar daya beli meningkat' termasuk pernyataan…","options":["ekonomi positif","ekonomi deskriptif","ekonomi mikro murni","ekonomi normatif"],"key":[3],"why":"Kata 'seharusnya' menunjukkan pertimbangan nilai subjektif tentang apa yang sebaiknya dilakukan (ekonomi normatif).","src":"kuis"},{"id":"0.0.2","topic":"Konsep Dasar Ekonomi","sub":"1.1 Hakikat, Pembagian & Prinsip Ilmu Ekonomi","kind":"pg","stem":"Seorang pedagang membandingkan harga grosir dari tiga pemasok agar memperoleh barang berkualitas sama dengan harga termurah. Tindakan pedagang tersebut menerapkan…","options":["prinsip ekonomi","ekonomi makro","motif sosial","hukum penawaran"],"key":[0],"why":"Prinsip ekonomi adalah pedoman mencapai hasil tertentu dengan pengorbanan sekecil-kecilnya.","src":"kuis"},{"id":"0.1.0","topic":"Konsep Dasar Ekonomi","sub":"1.2 Kelangkaan (Scarcity), Kebutuhan & Skala Prioritas","kind":"pg","stem":"Inti masalah ekonomi yang dihadapi manusia sepanjang masa adalah…","options":["kelangkaan sumber daya dibanding kebutuhan yang tak terbatas","ketidakstabilan kurs mata uang","kurangnya jumlah uang yang beredar di masyarakat","tingginya tarif pajak penghasilan"],"key":[0],"why":"Inti masalah ilmu ekonomi (scarcity) adalah kesenjangan antara kebutuhan manusia yang tidak terbatas dengan alat pemuas kebutuhan yang terbatas.","src":"kuis"},{"id":"0.1.1","topic":"Konsep Dasar Ekonomi","sub":"1.2 Kelangkaan (Scarcity), Kebutuhan & Skala Prioritas","kind":"pg","stem":"Ketika harga tiket pesawat naik tajam, permintaan tiket kereta api eksekutif rute yang sama meningkat. Hal ini menunjukkan pesawat dan kereta api merupakan barang…","options":["inferior","komplementer","illith","substitusi"],"key":[3],"why":"Barang substitusi saling menggantikan: kenaikan harga barang A mendorong konsumen beralih membeli barang B.","src":"kuis"},{"id":"0.1.2","topic":"Konsep Dasar Ekonomi","sub":"1.2 Kelangkaan (Scarcity), Kebutuhan & Skala Prioritas","kind":"pg","stem":"Bagi seorang pelajar SMA yang memiliki uang saku terbatas, pengeluaran yang harus ditempatkan pada Kuadran I (Penting dan Mendesak) adalah…","options":["membeli jaket bermerek yang sedang diskon","membeli tiket konser musik bulan depan","menabung untuk membeli sepeda motor tahun depan","membayar uang buku cetak ujian dan makan siang hari ini"],"key":[3],"why":"Buku ujian dan makan harian bersifat vital bagi kelangsungan belajar dan harus dipenuhi segera (penting & mendesak).","src":"kuis"},{"id":"0.2.0","topic":"Konsep Dasar Ekonomi","sub":"1.3 Biaya Peluang (Opportunity Cost) & Kurva PPF","kind":"pg","stem":"Budi ditawari bekerja di Bank dengan gaji Rp5.000.000, di Asuransi Rp4.500.000, atau di Retail Rp4.000.000. Jika Budi memilih bekerja di Bank, berapa biaya peluangnya?","options":["Rp8.500.000","Rp5.000.000","Rp4.500.000","Rp4.000.000"],"key":[2],"why":"Biaya peluang adalah satu alternatif terbaik yang dikorbankan, yaitu tawaran tertinggi di luar pilihan yang diambil: Rp4.500.000.","src":"kuis"},{"id":"0.2.1","topic":"Konsep Dasar Ekonomi","sub":"1.3 Biaya Peluang (Opportunity Cost) & Kurva PPF","kind":"pg","stem":"Pada Kurva Kemungkinan Produksi (PPF), titik yang berada di sebelah dalam (di bawah) garis kurva menunjukkan kondisi…","options":["ketidakefisienan / adanya sumber daya yang menganggur","kombinasi yang belum dapat dicapai teknologi saat ini","efisiensi produksi maksimum","pertumbuhan ekonomi jangka panjang"],"key":[0],"why":"Titik di dalam kurva PPF menandakan belum semua faktor produksi terpakai (terjadi pengangguran/pemborosan).","src":"kuis"},{"id":"0.2.2","topic":"Konsep Dasar Ekonomi","sub":"1.3 Biaya Peluang (Opportunity Cost) & Kurva PPF","kind":"pg","stem":"Mengapa bentuk kurva PPF umumnya melengkung cekung terhadap titik asal (origin)?","options":["Karena berlakunya hukum biaya peluang yang semakin meningkat (increasing opportunity cost)","Karena sumber daya dapat dipindahkan antarindustri dengan kecocokan yang sama persis","Karena biaya peluang bersifat konstan","Karena harga barang selalu turun"],"key":[0],"why":"Sumber daya bersifat spesifik; memindahkan sumber daya yang makin tidak cocok ke produksi barang lain menuntut pengorbanan yang makin besar.","src":"kuis"},{"id":"0.3.0","topic":"Konsep Dasar Ekonomi","sub":"1.4 Masalah Pokok Ekonomi & Sistem Ekonomi","kind":"pg","stem":"Pertanyaan mengenai apakah proyek jalan desa akan dikerjakan secara padat karya (menyerap warga lokal) atau menggunakan alat berat berkaitan dengan masalah pokok ekonomi…","options":["What","When","How","For Whom"],"key":[2],"why":"How menyangkut metode, teknik produksi, dan kombinasi faktor produksi (padat karya vs padat modal).","src":"kuis"},{"id":"0.3.1","topic":"Konsep Dasar Ekonomi","sub":"1.4 Masalah Pokok Ekonomi & Sistem Ekonomi","kind":"pg","stem":"Ciri utama Sistem Ekonomi Komando (Terpusat) adalah…","options":["seluruh faktor produksi dikuasai negara dan harga ditentukan pemerintah pusat","persaingan bebas antarpelaku usaha swasta","peran pemerintah hanya sebagai pengawas regulasi","kebebasan penuh individu memiliki alat produksi"],"key":[0],"why":"Dalam sistem komando, negara menguasai seluruh faktor produksi dan merencanakan What, How, For Whom secara terpusat.","src":"kuis"},{"id":"0.3.2","topic":"Konsep Dasar Ekonomi","sub":"1.4 Masalah Pokok Ekonomi & Sistem Ekonomi","kind":"pg","stem":"Karakteristik Sistem Demokrasi Ekonomi di Indonesia berdasarkan Pasal 33 UUD 1945 adalah…","options":["perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan","negara menyerahkan cabang produksi vital sepenuhnya kepada mekanisme pasar","persaingan bebas tanpa intervensi negara","hak milik perorangan dihapuskan seluruhnya"],"key":[0],"why":"Pasal 33 ayat (1) UUD 1945 menegaskan perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan.","src":"kuis"},{"id":"0.4.0","topic":"Konsep Dasar Ekonomi","sub":"1.5 Kegiatan & Pelaku Ekonomi (Circular Flow Diagram)","kind":"pg","stem":"Dalam diagram arus lingkar (Circular Flow), arus uang yang mengalir dari Rumah Tangga Produsen (RTP) ke Rumah Tangga Konsumen (RTK) melalui pasar input merupakan…","options":["pembayaran sewa, upah, bunga, dan laba atas penggunaan faktor produksi","pembayaran pajak penghasilan","pemberian subsidi pemerintah","pembelian barang dan jasa konsumsi"],"key":[0],"why":"RTP menggunakan faktor produksi milik RTK sehingga membayar balas jasa berupa sewa, upah, bunga, dan laba.","src":"kuis"},{"id":"0.4.1","topic":"Konsep Dasar Ekonomi","sub":"1.5 Kegiatan & Pelaku Ekonomi (Circular Flow Diagram)","kind":"pg","stem":"Siapakah pemilik faktor produksi (tanah, tenaga kerja, modal, kewirausahaan) dalam kegiatan ekonomi?","options":["Rumah Tangga Produsen (RTP)","Rumah Tangga Konsumen (RTK)","Masyarakat Luar Negeri","Bank Sentral"],"key":[1],"why":"Rumah Tangga Konsumen (RTK) adalah pemilik faktor produksi yang menawarkan inputnya kepada perusahaan (RTP).","src":"kuis"},{"id":"0.4.2","topic":"Konsep Dasar Ekonomi","sub":"1.5 Kegiatan & Pelaku Ekonomi (Circular Flow Diagram)","kind":"pg","stem":"Manakah yang merupakan peran Rumah Tangga Pemerintah (RTN) sebagai pengatur sekaligus konsumen dalam perekonomian?","options":["Menetapkan kebijakan pajak dan membeli alat tulis kantor untuk kementerian","Menciptakan uang giral melalui penyaluran kredit","Mengekspor bahan mentah ke luar negeri","Menentukan selera konsumen secara paksa"],"key":[0],"why":"Menetapkan pajak adalah peran regulator/pengatur, sedangkan membeli perlengkapan kantor kementerian adalah peran konsumen.","src":"kuis"},{"id":"0.5.0","topic":"Konsep Dasar Ekonomi","sub":"1.6 Perilaku Konsumen (Utilitas) & Perilaku Produsen (Biaya & Laba)","kind":"pg","stem":"Bunyi Hukum Gossen I adalah…","options":["jika harga naik maka permintaan turun","jika konsumsi suatu barang dilakukan terus-menerus, tambahan kepuasan (MU) akan makin menurun hingga akhirnya nol","manusia berusaha memenuhi beragam kebutuhannya sampai tingkat intensitas yang sama","tambahan input variabel akhirnya menurunkan produk marjinal"],"key":[1],"why":"Hukum Gossen I (Law of Diminishing Marginal Utility) menyatakan tambahan kepuasan (MU) terus menurun seiring bertambahnya unit yang dikonsumsi.","src":"kuis"},{"id":"0.5.1","topic":"Konsep Dasar Ekonomi","sub":"1.6 Perilaku Konsumen (Utilitas) & Perilaku Produsen (Biaya & Laba)","kind":"pg","stem":"Konsumen mengonsumsi barang X (Px = Rp2.000) dan barang Y (Py = Rp4.000). Jika MUx saat ini = 30 util, maka keseimbangan konsumen (kepuasan maksimum) tercapai saat MUy sebesar…","options":["60 util","30 util","15 util","120 util"],"key":[0],"why":"Syarat kepuasan maksimum (Gossen II): MUx/Px = MUy/Py → 30/2.000 = MUy/4.000 → MUy = 60 util.","src":"kuis"},{"id":"0.5.2","topic":"Konsep Dasar Ekonomi","sub":"1.6 Perilaku Konsumen (Utilitas) & Perilaku Produsen (Biaya & Laba)","kind":"pg","stem":"Perusahaan memperoleh laba maksimum apabila berproduksi pada tingkat output di mana…","options":["AC = MC","TR = TC","FC = VC","MR = MC"],"key":[3],"why":"Laba maksimum (atau rugi minimum) selalu dicapai pada saat penerimaan marjinal sama dengan biaya marjinal (MR = MC).","src":"kuis"},{"id":"1.0.0","topic":"Ekonomi Mikro & Pasar","sub":"2.1 Permintaan (Demand): Hukum, Fungsi & Pergeseran Kurva","kind":"pg","stem":"Faktor apakah yang menyebabkan terjadinya pergerakan di sepanjang kurva permintaan (movement along the demand curve) tanpa menggeser kurva?","options":["Pertambahan jumlah penduduk","Perubahan harga barang substitusi","Kenaikan pendapatan masyarakat","Perubahan harga barang itu sendiri"],"key":[3],"why":"Perubahan harga barang itu sendiri hanya menggerakkan titik di sepanjang kurva permintaan yang sama; faktor selain harga menggeser kurva.","src":"kuis"},{"id":"1.0.1","topic":"Ekonomi Mikro & Pasar","sub":"2.1 Permintaan (Demand): Hukum, Fungsi & Pergeseran Kurva","kind":"pg","stem":"Apabila harga bahan bakar minyak (BBM) naik signifikan, bagaimana dampaknya terhadap kurva permintaan sepeda motor berbahan bakar bensin?","options":["Bergerak sepanjang kurva ke atas","Bergeser ke kiri","Bergeser ke kanan","Tetap tidak berubah"],"key":[1],"why":"BBM dan motor bensin adalah barang komplementer. Kenaikan harga BBM menurunkan permintaan motor bensin pada setiap tingkat harga (kurva D bergeser ke kiri).","src":"kuis"},{"id":"1.0.2","topic":"Ekonomi Mikro & Pasar","sub":"2.1 Permintaan (Demand): Hukum, Fungsi & Pergeseran Kurva","kind":"pg","stem":"Saat harga jeruk Rp15.000/kg permintaan 100 kg; saat harga Rp20.000/kg permintaan 80 kg. Fungsi permintaannya adalah…","options":["Qd = 160 + 0,004P","Qd = 160 − 0,004P","Qd = 200 − 0,005P","Qd = 100 − 0,004P"],"key":[1],"why":"ΔQ/ΔP = −20/5.000 = −0,004. Q − 100 = −0,004(P − 15.000) → Qd = 160 − 0,004P.","src":"kuis"},{"id":"1.1.0","topic":"Ekonomi Mikro & Pasar","sub":"2.2 Penawaran (Supply): Hukum, Fungsi & Pergeseran Kurva","kind":"pg","stem":"Manakah di antara fungsi berikut yang merupakan fungsi penawaran yang benar?","options":["Qs = 500 − 2P","Ps = 10.000 − 4Q","Q + 3P = 600","Qs = −100 + 0,5P"],"key":[3],"why":"Fungsi penawaran memiliki hubungan positif antara P dan Q (koefisien P terhadap Q bertanda positif).","src":"kuis"},{"id":"1.1.1","topic":"Ekonomi Mikro & Pasar","sub":"2.2 Penawaran (Supply): Hukum, Fungsi & Pergeseran Kurva","kind":"pg","stem":"Kemajuan teknologi mesin pertanian yang memangkas biaya panen padi sebesar 40% akan berdampak pada…","options":["pergeseran kurva penawaran beras ke kiri","pergeseran kurva permintaan beras ke kiri","kenaikan harga keseimbangan beras","pergeseran kurva penawaran beras ke kanan"],"key":[3],"why":"Efisiensi teknologi dan penurunan biaya produksi meningkatkan penawaran pada setiap tingkat harga sehingga kurva S bergeser ke kanan.","src":"kuis"},{"id":"1.1.2","topic":"Ekonomi Mikro & Pasar","sub":"2.2 Penawaran (Supply): Hukum, Fungsi & Pergeseran Kurva","kind":"pg","stem":"Jika pemerintah mencabut subsidi pupuk bagi petani cabai, maka yang terjadi pada pasar cabai adalah…","options":["harga keseimbangan cabai turun","kurva penawaran cabai bergeser ke kiri sehingga harga keseimbangan naik","kurva penawaran cabai bergeser ke kanan","kurva permintaan cabai bergeser ke kanan"],"key":[1],"why":"Pencabutan subsidi menaikkan biaya produksi petani sehingga kurva penawaran S bergeser ke kiri dan harga pasar naik.","src":"kuis"},{"id":"1.2.0","topic":"Ekonomi Mikro & Pasar","sub":"2.3 Keseimbangan Pasar, Surplus & Kebijakan Harga Pemerintah","kind":"pg","stem":"Kebijakan Harga Eceran Tertinggi (Ceiling Price) yang efektif ditetapkan pemerintah pada tingkat harga…","options":["sama persis dengan harga keseimbangan","di bawah harga keseimbangan untuk melindungi daya beli konsumen","di atas harga keseimbangan untuk melindungi produsen","setinggi-tingginya agar pajak meningkat"],"key":[1],"why":"Ceiling price (HET) ditetapkan di bawah harga pasar (Pe) agar harga tetap terjangkau oleh konsumen.","src":"kuis"},{"id":"1.2.1","topic":"Ekonomi Mikro & Pasar","sub":"2.3 Keseimbangan Pasar, Surplus & Kebijakan Harga Pemerintah","kind":"pg","stem":"Dampak langsung dari penetapan Harga Dasar (Floor Price) gabah di atas harga keseimbangan pasar adalah…","options":["harga pasar otomatis turun di bawah harga dasar","terjadinya kelebihan permintaan (shortage)","terjadinya kelebihan penawaran (surplus gabah) yang perlu diserap pemerintah","petani berhenti menanam padi"],"key":[2],"why":"Pada harga di atas Pe, jumlah yang ditawarkan petani (Qs) melebihi jumlah yang diminta pembeli (Qd), menciptakan excess supply.","src":"kuis"},{"id":"1.2.2","topic":"Ekonomi Mikro & Pasar","sub":"2.3 Keseimbangan Pasar, Surplus & Kebijakan Harga Pemerintah","kind":"pg","stem":"Jika fungsi permintaan Pd = 50 − 2Q dan harga pasar terbentuk pada P = 30 (Qe = 10), berapakah besarnya Surplus Konsumen (CS)?","options":["200","150","50","100"],"key":[3],"why":"CS = ½ × (P<sub>maks</sub> − Pe) × Qe = ½ × (50 − 30) × 10 = 100.","src":"kuis"},{"id":"1.3.0","topic":"Ekonomi Mikro & Pasar","sub":"2.4 Pengaruh Pajak & Subsidi terhadap Keseimbangan Pasar","kind":"pg","stem":"Diketahui fungsi penawaran Qs = −10 + 2P. Jika pemerintah mengenakan pajak Rp3 per unit, maka fungsi penawaran setelah pajak adalah…","options":["Qs' = −10 + 2(P + 3)","Qs' = −4 + 2P","Qs' = −16 + 2P","Qs' = −10 + 2P + 3"],"key":[2],"why":"Substitusikan P dengan (P − t): Qs' = −10 + 2(P − 3) = −10 + 2P − 6 = −16 + 2P.","src":"kuis"},{"id":"1.3.1","topic":"Ekonomi Mikro & Pasar","sub":"2.4 Pengaruh Pajak & Subsidi terhadap Keseimbangan Pasar","kind":"pg","stem":"Pemberian subsidi pemerintah sebesar s per unit atas suatu komoditas akan menyebabkan…","options":["harga keseimbangan turun dan jumlah keseimbangan naik","harga keseimbangan naik dan jumlah keseimbangan turun","kurva permintaan bergeser ke kiri","beban pajak konsumen meningkat"],"key":[0],"why":"Subsidi menurunkan biaya penawaran (Ps' = Ps − s), menggeser kurva S ke kanan bawah sehingga Pe turun dan Qe naik.","src":"kuis"},{"id":"1.3.2","topic":"Ekonomi Mikro & Pasar","sub":"2.4 Pengaruh Pajak & Subsidi terhadap Keseimbangan Pasar","kind":"pg","stem":"Harga keseimbangan sebelum pajak Rp10.000 dan setelah pajak Rp4.000/unit harga keseimbangan menjadi Rp12.500. Beban pajak per unit yang ditanggung produsen adalah…","options":["Rp6.500","Rp2.500","Rp1.500","Rp4.000"],"key":[2],"why":"tk = 12.500 − 10.000 = Rp2.500. Maka beban produsen tp = t − tk = 4.000 − 2.500 = Rp1.500.","src":"kuis"},{"id":"1.4.0","topic":"Ekonomi Mikro & Pasar","sub":"2.5 Elastisitas Permintaan & Penawaran","kind":"pg","stem":"Suatu barang memiliki koefisien elastisitas harga permintaan Ed = 0,4. Strategi yang tepat bagi produsen untuk meningkatkan penerimaan total (TR) adalah…","options":["menghentikan produksi","memberikan diskon besar-besaran","menurunkan harga jual","menaikkan harga jual"],"key":[3],"why":"Ed = 0,4 < 1 (Inelastis): konsumen tidak peka terhadap kenaikan harga (%ΔQ < %ΔP), sehingga menaikkan harga akan meningkatkan TR.","src":"kuis"},{"id":"1.4.1","topic":"Ekonomi Mikro & Pasar","sub":"2.5 Elastisitas Permintaan & Penawaran","kind":"pg","stem":"Kebutuhan pokok seperti beras dan garam umumnya memiliki permintaan yang bersifat…","options":["elastis (E > 1)","elastis uniter (E = 1)","inelastis (E < 1)","elastis sempurna (E = ∞)"],"key":[2],"why":"Barang kebutuhan pokok tidak mudah ditunda atau digantikan, sehingga meskipun harga naik, konsumsi hanya turun sedikit (inelastis).","src":"kuis"},{"id":"1.4.2","topic":"Ekonomi Mikro & Pasar","sub":"2.5 Elastisitas Permintaan & Penawaran","kind":"pg","stem":"Jika elastisitas silang antara barang X dan barang Y bernilai negatif (Exy < 0), maka hubungan kedua barang tersebut adalah…","options":["barang tidak berhubungan","saling melengkapi (komplementer)","saling menggantikan (substitusi)","barang mewah"],"key":[1],"why":"Exy < 0 berarti kenaikan harga barang Y menurunkan permintaan barang X (contoh: bensin dan mobil → komplementer).","src":"kuis"},{"id":"1.5.0","topic":"Ekonomi Mikro & Pasar","sub":"2.6 Struktur Pasar Output & Pasar Input (Faktor Produksi)","kind":"pg","stem":"Pasar di mana terdapat banyak produsen yang menjual produk serupa tetapi memiliki perbedaan merek, kemasan, dan gencar beriklan (seperti industri sampo dan pasta gigi) disebut pasar…","options":["oligopoli","monopoli","persaingan monopolistik","persaingan sempurna"],"key":[2],"why":"Diferensiasi produk (merek, kualitas, kemasan) dengan banyak penjual adalah ciri khas pasar persaingan monopolistik.","src":"kuis"},{"id":"1.5.1","topic":"Ekonomi Mikro & Pasar","sub":"2.6 Struktur Pasar Output & Pasar Input (Faktor Produksi)","kind":"pg","stem":"Mengapa kurva permintaan yang dihadapi satu perusahaan pada Pasar Persaingan Sempurna berbentuk garis lurus horizontal?","options":["Karena perusahaan dapat menaikkan harga sesuka hati","Karena perusahaan adalah price taker yang dapat menjual berapa pun output pada tingkat harga pasar yang berlaku","Karena barang tidak memiliki substitusi","Karena konsumen tidak mengetahui informasi harga"],"key":[1],"why":"Sebagai price taker, satu penjual kecil tidak bisa memengaruhi harga pasar: P = AR = MR konstan (horizontal).","src":"kuis"},{"id":"1.5.2","topic":"Ekonomi Mikro & Pasar","sub":"2.6 Struktur Pasar Output & Pasar Input (Faktor Produksi)","kind":"pg","stem":"Teori sewa tanah yang menyatakan bahwa tinggi rendahnya sewa tanah ditentukan oleh perbedaan tingkat kesuburan tanah dikemukakan oleh…","options":["David Ricardo","Von Thunen","Adam Smith","John Maynard Keynes"],"key":[0],"why":"David Ricardo mengemukakan teori sewa tanah diferensial berdasarkan kesuburan tanah; sedangkan Von Thunen berdasarkan jarak/lokasi ke pasar.","src":"kuis"},{"id":"2.0.0","topic":"Makro: PDB & Tenaga Kerja","sub":"3.1 Konsep Pendapatan Nasional (GDP hingga DI)","kind":"pg","stem":"Jika di suatu negara nilai Produk Domestik Bruto (GDP) lebih besar daripada Produk Nasional Bruto (GNP), hal ini menunjukkan bahwa…","options":["penyusutan barang modal bernilai nol","pendapatan warga negara tersebut di luar negeri lebih besar daripada pendapatan warga asing di dalam negeri","ekspor negara tersebut lebih besar daripada impornya","nilai investasi/pendapatan faktor produksi asing di dalam negeri lebih besar daripada pendapatan warga negara tersebut di luar negeri"],"key":[3],"why":"GNP = GDP + (WNI di LN − WNA di DN). Jika GDP > GNP, berarti pendapatan WNA di dalam negeri lebih besar daripada pendapatan WNI di luar negeri.","src":"kuis"},{"id":"2.0.1","topic":"Makro: PDB & Tenaga Kerja","sub":"3.1 Konsep Pendapatan Nasional (GDP hingga DI)","kind":"pg","stem":"Komponen yang MENAMBAH nilai saat menghitung Personal Income (PI) dari Net National Income (NNI) adalah…","options":["laba ditahan","iuran jaminan sosial","transfer payment (pembayaran pindahan seperti dana pensiun dan bansos)","pajak perseroan"],"key":[2],"why":"Transfer payment diterima oleh rumah tangga meskipun bukan balas jasa produksi tahun berjalan, sehingga menambah PI.","src":"kuis"},{"id":"2.0.2","topic":"Makro: PDB & Tenaga Kerja","sub":"3.1 Konsep Pendapatan Nasional (GDP hingga DI)","kind":"pg","stem":"Pendapatan yang benar-benar siap dibelanjakan oleh rumah tangga untuk konsumsi atau ditabung setelah dikurangi pajak penghasilan pribadi disebut…","options":["Gross National Product (GNP)","Personal Income (PI)","Disposable Income (DI)","Net National Income (NNI)"],"key":[2],"why":"Disposable Income (DI = PI − Pajak Langsung) adalah pendapatan siap pakai untuk konsumsi (C) dan tabungan (S).","src":"kuis"},{"id":"2.1.0","topic":"Makro: PDB & Tenaga Kerja","sub":"3.2 Tiga Metode Perhitungan, Fungsi Konsumsi & Multiplier","kind":"pg","stem":"Dalam perhitungan pendapatan nasional dengan pendekatan produksi, mengapa yang dijumlahkan hanya 'nilai tambah' (value added) tiap tahap produksi?","options":["Karena harga barang jadi selalu lebih murah dari bahan mentah","Untuk menghindari perhitungan ganda (double counting) atas bahan baku yang sama","Untuk memperkecil beban pajak perusahaan","Karena pendekatan produksi tidak menghitung sektor jasa"],"key":[1],"why":"Jika nilai barang jadi dan nilai bahan mentah dijumlahkan seluruhnya, nilai kapas/benang akan terhitung berkali-kali (double counting).","src":"kuis"},{"id":"2.1.1","topic":"Makro: PDB & Tenaga Kerja","sub":"3.2 Tiga Metode Perhitungan, Fungsi Konsumsi & Multiplier","kind":"pg","stem":"Komponen terbesar dalam perhitungan Produk Domestik Bruto (PDB) Indonesia melalui pendekatan pengeluaran (Y = C + I + G + X − M) adalah…","options":["Ekspor Bersih (X − M)","Subsidi Sosial","Pengeluaran Pemerintah (G)","Konsumsi Rumah Tangga (C)"],"key":[3],"why":"Konsumsi rumah tangga (C) menyumbang lebih dari separuh (>50%) total PDB Indonesia.","src":"kuis"},{"id":"2.1.2","topic":"Makro: PDB & Tenaga Kerja","sub":"3.2 Tiga Metode Perhitungan, Fungsi Konsumsi & Multiplier","kind":"pg","stem":"Saat pendapatan keluarga naik dari Rp4.000.000 menjadi Rp6.000.000, pengeluaran konsumsinya naik dari Rp3.500.000 menjadi Rp5.000.000. Besarnya MPS (Marginal Propensity to Save) adalah…","options":["0,75","0,20","0,25","0,50"],"key":[2],"why":"MPC = ΔC/ΔY = 1.500.000 / 2.000.000 = 0,75. Karena MPC + MPS = 1, maka MPS = 1 − 0,75 = 0,25.","src":"kuis"},{"id":"2.2.0","topic":"Makro: PDB & Tenaga Kerja","sub":"3.3 Pendapatan Per Kapita & Distribusi Pendapatan (Gini & Lorenz)","kind":"pg","stem":"Apabila Kurva Lorenz suatu negara semakin menjauhi garis diagonal pemerataan (45°), maka hal tersebut mengindikasikan…","options":["koefisien Gini mendekati angka 0","pendapatan per kapita pasti menurun","ketimpangan distribusi pendapatan semakin tinggi (koefisien Gini mendekati 1)","distribusi pendapatan masyarakat semakin merata"],"key":[2],"why":"Semakin lengkung/jauh Kurva Lorenz dari garis diagonal, semakin besar luas daerah ketimpangan dan semakin mendekati 1 nilai Indeks Gini.","src":"kuis"},{"id":"2.2.1","topic":"Makro: PDB & Tenaga Kerja","sub":"3.3 Pendapatan Per Kapita & Distribusi Pendapatan (Gini & Lorenz)","kind":"pg","stem":"Menurut kriteria Bank Dunia, suatu negara dikategorikan memiliki tingkat ketimpangan distribusi pendapatan yang RENDAH apabila 40% penduduk termiskin menerima porsi pendapatan nasional…","options":["lebih dari 17%","tepat 10%","kurang dari 12%","antara 12% sampai 17%"],"key":[0],"why":"Kriteria Bank Dunia untuk 40% penduduk termiskin: <12% (ketimpangan tinggi), 12%–17% (sedang), dan >17% (ketimpangan rendah).","src":"kuis"},{"id":"2.2.2","topic":"Makro: PDB & Tenaga Kerja","sub":"3.3 Pendapatan Per Kapita & Distribusi Pendapatan (Gini & Lorenz)","kind":"pg","stem":"Koefisien Gini sebesar 0,25 menunjukkan bahwa distribusi pendapatan di wilayah tersebut berada pada kategori…","options":["ketimpangan mutlak","ketimpangan tinggi","ketimpangan sedang","ketimpangan rendah (merata)"],"key":[3],"why":"Indeks Gini < 0,30 dikategorikan ketimpangan rendah; 0,30–0,50 sedang; > 0,50 ketimpangan tinggi.","src":"kuis"},{"id":"2.3.0","topic":"Makro: PDB & Tenaga Kerja","sub":"3.4 Pertumbuhan Ekonomi vs Pembangunan Ekonomi","kind":"pg","stem":"Perbedaan mendasar antara pertumbuhan ekonomi dan pembangunan ekonomi adalah…","options":["pertumbuhan ekonomi hanya mengukur kenaikan kuantitatif output (PDB), sedangkan pembangunan mencakup peningkatan kualitas hidup (IPM) dan perubahan struktur sosial","pembangunan ekonomi tidak memerlukan pertumbuhan output","pertumbuhan ekonomi bersifat kualitatif, sedangkan pembangunan bersifat kuantitatif","pertumbuhan ekonomi selalu memperhatikan distribusi pendapatan"],"key":[0],"why":"Pertumbuhan ekonomi = kenaikan kuantitatif PDB riil; pembangunan ekonomi = kenaikan output + kualitas SDM (IPM), pemerataan, dan transformasi struktural.","src":"kuis"},{"id":"2.3.1","topic":"Makro: PDB & Tenaga Kerja","sub":"3.4 Pertumbuhan Ekonomi vs Pembangunan Ekonomi","kind":"pg","stem":"Tokoh ekonomi yang menyatakan bahwa pertumbuhan ekonomi digerakkan oleh inovasi dan keberanian wirausahawan (entrepreneur) melakukan terobosan baru adalah…","options":["David Ricardo","Joseph Schumpeter","Adam Smith","Thomas Robert Malthus"],"key":[1],"why":"Joseph Schumpeter menekankan peran sentral inovasi oleh entrepreneur (creative destruction) sebagai motor pertumbuhan ekonomi.","src":"kuis"},{"id":"2.3.2","topic":"Makro: PDB & Tenaga Kerja","sub":"3.4 Pertumbuhan Ekonomi vs Pembangunan Ekonomi","kind":"pg","stem":"Tiga dimensi utama pembentuk Indeks Pembangunan Manusia (IPM / Human Development Index) adalah…","options":["sektor pertanian, industri, dan jasa","umur panjang & hidup sehat, pengetahuan (pendidikan), serta standar hidup layak","inflasi, nilai tukar, dan suku bunga","jumlah penduduk, luas wilayah, dan cadangan devisa"],"key":[1],"why":"UNDP dan BPS menghitung IPM dari tiga dimensi: kesehatan (angka harapan hidup), pendidikan (HLS & RLS), dan ekonomi (pengeluaran per kapita riil).","src":"kuis"},{"id":"2.4.0","topic":"Makro: PDB & Tenaga Kerja","sub":"3.5 Ketenagakerjaan, Angkatan Kerja & Pengangguran","kind":"pg","stem":"Seorang lulusan SMK jurusan otomotif belum mendapatkan pekerjaan karena pabrik di daerahnya beralih memproduksi komponen semikonduktor yang menuntut keahlian pemrograman. Jenis pengangguran ini beserta solusi tepatnya adalah…","options":["Pengangguran struktural — solusi: pelatihan vokasi ulang (reskilling/upskilling) sesuai kebutuhan industri","Pengangguran friksional — solusi: menaikkan upah minimum","Pengangguran musiman — solusi: memberi bantuan tunai seumur hidup","Pengangguran sukarela — solusi: menurunkan pajak ekspor"],"key":[0],"why":"Ketidaksesuaian keterampilan tenaga kerja dengan perubahan struktur industri adalah pengangguran struktural; diatasi dengan pelatihan keterampilan baru.","src":"kuis"},{"id":"2.4.1","topic":"Makro: PDB & Tenaga Kerja","sub":"3.5 Ketenagakerjaan, Angkatan Kerja & Pengangguran","kind":"pg","stem":"Siswa SMA berusia 17 tahun dan ibu rumah tangga yang fokus mengurus keluarga dalam statistik ketenagakerjaan dikelompokkan sebagai…","options":["angkatan kerja produktif","setengah menganggur","bukan angkatan kerja","pengangguran terbuka"],"key":[2],"why":"Penduduk usia ≥15 tahun yang bersekolah, kuliah, atau mengurus rumah tangga termasuk Bukan Angkatan Kerja, sehingga tidak dihitung sebagai pengangguran.","src":"kuis"},{"id":"2.4.2","topic":"Makro: PDB & Tenaga Kerja","sub":"3.5 Ketenagakerjaan, Angkatan Kerja & Pengangguran","kind":"pg","stem":"Pekerja yang hanya bekerja 20 jam per minggu dan masih berusaha mencari tambahan pekerjaan dikategorikan sebagai…","options":["pengangguran friksional","pengangguran terbuka","bukan angkatan kerja","setengah menganggur (underemployed)"],"key":[3],"why":"Jam kerja normal BPS adalah ≥35 jam/minggu; bekerja <35 jam/minggu dan masih mencari kerja tambahan disebut setengah menganggur.","src":"kuis"},{"id":"2.5.0","topic":"Makro: PDB & Tenaga Kerja","sub":"3.6 Sistem Upah & Pasar Tenaga Kerja","kind":"pg","stem":"Di pasar faktor produksi tenaga kerja, pihak yang bertindak sebagai PENAWAR (supply) tenaga kerja adalah…","options":["perusahaan manufaktur","pemerintah daerah","rumah tangga konsumen (pekerja/pencari kerja)","bank umum"],"key":[2],"why":"Rumah tangga (RTK/pekerja) menawarkan jasa tenaga kerjanya, sedangkan perusahaan (RTP) adalah pihak yang meminta/membutuhkan tenaga kerja.","src":"kuis"},{"id":"2.5.1","topic":"Makro: PDB & Tenaga Kerja","sub":"3.6 Sistem Upah & Pasar Tenaga Kerja","kind":"pg","stem":"Permintaan perusahaan terhadap tenaga kerja disebut sebagai 'permintaan turunan' (derived demand) karena…","options":["diturunkan dari peraturan menteri ketenagakerjaan","upah selalu turun setiap tahun","bergantung pada besarnya permintaan masyarakat terhadap barang dan jasa yang diproduksi perusahaan tersebut","hanya berlaku bagi pekerja turun-temurun"],"key":[2],"why":"Perusahaan merekrut pekerja karena ada permintaan konsumen atas produk yang dibuat pekerja tersebut.","src":"kuis"},{"id":"2.5.2","topic":"Makro: PDB & Tenaga Kerja","sub":"3.6 Sistem Upah & Pasar Tenaga Kerja","kind":"pg","stem":"Sistem pengupahan pada tukang jahit konveksi yang dibayar Rp15.000 untuk setiap potong kemeja yang berhasil diselesaikan disebut…","options":["upah borongan proyek","upah mitra saham","upah satuan hasil (potongan)","upah menurut waktu"],"key":[2],"why":"Pembayaran berdasarkan jumlah unit fisik output yang dihasilkan disebut sistem upah satuan hasil/potongan.","src":"kuis"},{"id":"3.0.0","topic":"Inflasi, Moneter & Fiskal","sub":"4.1 Indeks Harga (Agregatif, Laspeyres, Paasche & NTP)","kind":"pg","stem":"Perbedaan rumus Indeks Harga Laspeyres dan Indeks Harga Paasche terletak pada…","options":["Laspeyres menggunakan harga tahun dasar di pembilang, Paasche di penyebut","Laspeyres menggunakan penimbang kuantitas tahun dasar (Q₀), sedangkan Paasche menggunakan kuantitas tahun berjalan (Qₙ)","Paasche hanya menghitung satu jenis barang","Laspeyres tidak dikalikan 100"],"key":[1],"why":"Laspeyres = tertimbang kuantitas tahun dasar (Q₀); Paasche = tertimbang kuantitas tahun berjalan (Qₙ).","src":"kuis"},{"id":"3.0.1","topic":"Inflasi, Moneter & Fiskal","sub":"4.1 Indeks Harga (Agregatif, Laspeyres, Paasche & NTP)","kind":"pg","stem":"Di Provinsi Jawa Timur tercatat Indeks Harga yang Diterima Petani (IT) sebesar 118 dan Indeks Harga yang Dibayar Petani (IB) sebesar 112. Kesimpulan yang tepat adalah…","options":["Petani mengalami kebangkrutan karena IB > 100","NTP < 100, kesejahteraan petani menurun","NTP = 105,36 > 100, petani mengalami surplus (daya beli petani meningkat)","Tidak terjadi inflasi di pedesaan"],"key":[2],"why":"NTP = (118 / 112) × 100 = 105,36 (>100), artinya kenaikan harga hasil panen petani lebih besar daripada kenaikan biaya produksi & konsumsi petani.","src":"kuis"},{"id":"3.0.2","topic":"Inflasi, Moneter & Fiskal","sub":"4.1 Indeks Harga (Agregatif, Laspeyres, Paasche & NTP)","kind":"pg","stem":"Jika Indeks Laspeyres = 124 dan Indeks Paasche = 126, maka Indeks Drobisch adalah…","options":["120","250","125","124,5"],"key":[2],"why":"Indeks Drobisch adalah rata-rata hitung IL dan IP: (124 + 126) / 2 = 125.","src":"kuis"},{"id":"3.1.0","topic":"Inflasi, Moneter & Fiskal","sub":"4.2 Inflasi: Konsep, Penyebab, Perhitungan & Dampak","kind":"pg","stem":"Kenaikan harga barang secara umum yang dipicu oleh lonjakan tarif listrik industri, upah buruh, dan harga bahan baku impor disebut…","options":["demand-pull inflation","cost-push inflation","apresiasi","deflasi"],"key":[1],"why":"Kenaikan biaya produksi yang menggeser kurva penawaran agregat (AS) ke kiri disebut cost-push inflation.","src":"kuis"},{"id":"3.1.1","topic":"Inflasi, Moneter & Fiskal","sub":"4.2 Inflasi: Konsep, Penyebab, Perhitungan & Dampak","kind":"pg","stem":"Menurut teori kuantitas uang Irving Fisher (M × V = P × T), apabila kecepatan peredaran uang (V) dan jumlah barang yang diperdagangkan (T) tetap, sedangkan jumlah uang beredar (M) meningkat 20%, maka…","options":["tidak terjadi perubahan harga","nilai uang menguat 20%","tingkat harga umum (P) akan naik 20%","tingkat harga umum (P) akan turun 20%"],"key":[2],"why":"P = (M × V) / T. Jika V dan T konstan, tingkat harga P berbanding lurus dengan jumlah uang beredar M.","src":"kuis"},{"id":"3.1.2","topic":"Inflasi, Moneter & Fiskal","sub":"4.2 Inflasi: Konsep, Penyebab, Perhitungan & Dampak","kind":"pg","stem":"Siapakah pihak yang DIUNTUNGKAN ketika terjadi inflasi yang tidak terduga?","options":["Pensiunan dengan uang pensiun tetap setiap bulan","Debitur (peminjam uang) dengan suku bunga pinjaman tetap","Kreditor yang meminjamkan uang dengan bunga tetap","Penabung uang tunai di celengan"],"key":[1],"why":"Saat inflasi, nilai riil uang turun sehingga beban cicilan tetap yang dibayar debitur menjadi terasa lebih ringan secara riil.","src":"kuis"},{"id":"3.2.0","topic":"Inflasi, Moneter & Fiskal","sub":"4.3 Bank Sentral, Sistem Pembayaran & Uang","kind":"pg","stem":"Tujuan tunggal Bank Indonesia sebagai bank sentral Republik Indonesia adalah…","options":["mengawasi kegiatan operasional harian setiap perusahaan asuransi","menyalurkan kredit usaha rakyat secara langsung kepada UMKM","mengumpulkan pajak penghasilan untuk membiayai APBN","mencapai dan memelihara kestabilan nilai rupiah (terhadap barang/jasa dan mata uang asing)"],"key":[3],"why":"Sesuai UU Bank Indonesia, tujuan tunggal BI adalah mencapai dan memelihara kestabilan nilai rupiah (kestabilan inflasi dan kurs).","src":"kuis"},{"id":"3.2.1","topic":"Inflasi, Moneter & Fiskal","sub":"4.3 Bank Sentral, Sistem Pembayaran & Uang","kind":"pg","stem":"Seorang pengusaha mentransfer dana pembayaran gedung senilai Rp2,5 miliar secara instan (real-time settlement) antarbank untuk transaksi bernilai besar dan bersifat mendesak. Sistem pembayaran Bank Indonesia yang digunakan adalah…","options":["BI-RTGS (Real Time Gross Settlement)","QRIS","Uang Kartal","Cek Perjalanan"],"key":[0],"why":"BI-RTGS digunakan untuk penyelesaian transaksi dana bernilai besar (di atas Rp100 juta) dan bersifat segera/mendesak.","src":"kuis"},{"id":"3.2.2","topic":"Inflasi, Moneter & Fiskal","sub":"4.3 Bank Sentral, Sistem Pembayaran & Uang","kind":"pg","stem":"Nilai Rp100.000 yang tertulis pada selembar uang kertas pecahan seratus ribu rupiah disebut sebagai…","options":["nilai nominal","nilai intrinsik","nilai riil","nilai kurs"],"key":[0],"why":"Nilai nominal adalah nilai yang tercantum/tertulis pada uang; nilai intrinsik adalah nilai bahan pembuat uang tersebut.","src":"kuis"},{"id":"3.3.0","topic":"Inflasi, Moneter & Fiskal","sub":"4.4 Kebijakan Moneter (Ekspansif vs Kontraktif)","kind":"pg","stem":"Langkah Bank Sentral MENJUAL sertifikat surat berharga di pasar terbuka bertujuan untuk…","options":["menurunkan suku bunga pinjaman bank umum","mengurangi jumlah uang yang beredar untuk mengatasi inflasi","memperbesar kapasitas kredit perbankan","menambah jumlah uang yang beredar di masyarakat"],"key":[1],"why":"Saat Bank Sentral menjual surat berharga, pembeli membayar dengan uang kepada Bank Sentral sehingga uang yang beredar di masyarakat berkurang (mengatasi inflasi).","src":"kuis"},{"id":"3.3.1","topic":"Inflasi, Moneter & Fiskal","sub":"4.4 Kebijakan Moneter (Ekspansif vs Kontraktif)","kind":"pg","stem":"Jika Bank Sentral menetapkan Giro Wajib Minimum (GWM) sebesar 8%, maka angka pengganda uang (money multiplier) maksimum adalah…","options":["10 kali","80 kali","12,5 kali","8 kali"],"key":[2],"why":"m = 1 / GWM = 1 / 0,08 = 12,5 kali.","src":"kuis"},{"id":"3.3.2","topic":"Inflasi, Moneter & Fiskal","sub":"4.4 Kebijakan Moneter (Ekspansif vs Kontraktif)","kind":"pg","stem":"Ketika perekonomian mengalami kelesuan (resesi) dan daya beli masyarakat turun drastis, kebijakan moneter yang tepat diambil Bank Sentral adalah…","options":["menaikkan BI-Rate dan menjual SBN","menaikkan tarif Pajak Pertambahan Nilai (PPN)","menurunkan BI-Rate, menurunkan GWM, dan membeli SBN (Easy Money Policy)","menaikkan GWM dan memperketat syarat kredit"],"key":[2],"why":"Saat resesi dibutuhkan kebijakan moneter ekspansif (uang longgar): turunkan suku bunga, turunkan GWM, dan beli SBN agar likuiditas mengalir ke masyarakat.","src":"kuis"},{"id":"3.4.0","topic":"Inflasi, Moneter & Fiskal","sub":"4.5 APBN, APBD & Kebijakan Fiskal","kind":"pg","stem":"Kebijakan pemerintah melalui Kementerian Keuangan dalam mengatur penerimaan pajak dan belanja negara di dalam APBN untuk memengaruhi perekonomian disebut…","options":["kebijakan pasar terbuka","kebijakan diskonto","kebijakan moneter","kebijakan fiskal"],"key":[3],"why":"Pengaturan pajak (T) dan belanja pemerintah (G) dalam APBN adalah kebijakan fiskal.","src":"kuis"},{"id":"3.4.1","topic":"Inflasi, Moneter & Fiskal","sub":"4.5 APBN, APBD & Kebijakan Fiskal","kind":"pg","stem":"Pembangunan jalan tol, jembatan, dan bendungan irigasi oleh pemerintah melalui dana APBN merupakan perwujudan fungsi APBN, yaitu…","options":["fungsi moneter","fungsi alokasi","fungsi otorisasi semata","fungsi distribusi"],"key":[1],"why":"Fungsi alokasi mengarahkan sumber daya anggaran untuk menyediakan barang publik/infrastruktur guna mendorong kegiatan ekonomi.","src":"kuis"},{"id":"3.4.2","topic":"Inflasi, Moneter & Fiskal","sub":"4.5 APBN, APBD & Kebijakan Fiskal","kind":"pg","stem":"Jika perekonomian sedang mengalami inflasi yang sangat tinggi (overheating), kebijakan fiskal yang tepat ditempuh pemerintah adalah…","options":["menurunkan Giro Wajib Minimum perbankan","menurunkan suku bunga BI-Rate","menaikkan belanja negara dan menurunkan tarif pajak","mengurangi/menunda belanja pemerintah dan menaikkan tarif pajak (Fiskal Kontraktif)"],"key":[3],"why":"Untuk meredam permintaan agregat melalui jalur fiskal, pemerintah menahan belanja (G↓) dan/atau menaikkan pajak (T↑).","src":"kuis"},{"id":"3.5.0","topic":"Inflasi, Moneter & Fiskal","sub":"4.6 Perpajakan di Indonesia (Fungsi, Tarif & Perhitungan PPh)","kind":"pg","stem":"Pengenaan cukai yang tinggi terhadap rokok dan minuman berpemanis dengan tujuan menekan konsumsi masyarakat demi kesehatan merupakan perwujudan fungsi pajak…","options":["fungsi budgetair (anggaran)","fungsi moneter","fungsi demokrasi","fungsi regulerend (mengatur)"],"key":[3],"why":"Fungsi regulerend menggunakan pajak/cukai sebagai alat untuk mengatur dan mengarahkan perilaku ekonomi maupun sosial masyarakat.","src":"kuis"},{"id":"3.5.1","topic":"Inflasi, Moneter & Fiskal","sub":"4.6 Perpajakan di Indonesia (Fungsi, Tarif & Perhitungan PPh)","kind":"pg","stem":"Perbedaan utama antara pajak dan retribusi adalah…","options":["pajak dipungut oleh swasta, retribusi oleh negara","retribusi diatur undang-undang, pajak tidak","pajak bersifat sukarela, retribusi bersifat memaksa","pembayar pajak tidak menerima imbalan (kontraprestasi) langsung, sedangkan pembayar retribusi menerima imbalan langsung (seperti parkir atau pelayanan kesehatan)"],"key":[3],"why":"Pajak tidak memberikan kontraprestasi langsung kepada individu pembayarnya, sedangkan retribusi memberikan layanan/fasilitas langsung.","src":"kuis"},{"id":"3.5.2","topic":"Inflasi, Moneter & Fiskal","sub":"4.6 Perpajakan di Indonesia (Fungsi, Tarif & Perhitungan PPh)","kind":"pg","stem":"Sistem tarif pajak di mana persentase tarif pajaknya semakin meningkat seiring dengan semakin besarnya dasar pengenaan pajak (seperti PPh Orang Pribadi) disebut tarif…","options":["tetap (regresif)","degresif","progresif","proporsional (sebanding)"],"key":[2],"why":"Tarif progresif mengenakan persentase yang makin tinggi untuk lapisan penghasilan yang lebih tinggi demi keadilan vertikal.","src":"kuis"},{"id":"4.0.0","topic":"Badan Usaha & Internasional","sub":"5.1 Konsep Manajemen: Fungsi POAC, Tingkatan & Bidang","kind":"pg","stem":"Tindakan seorang manajer pabrik mengevaluasi laporan hasil produksi bulanan, membandingkannya dengan target rencana awal, dan memperbaiki penyebab keterlambatan merupakan pelaksanaan fungsi manajemen…","options":["Actuating (Penggerakan)","Planning (Perencanaan)","Controlling (Pengawasan)","Organizing (Pengorganisasian)"],"key":[2],"why":"Controlling mencakup penetapan standar, pengukuran kinerja aktual, pembandingan dengan rencana, dan tindakan koreksi.","src":"kuis"},{"id":"4.0.1","topic":"Badan Usaha & Internasional","sub":"5.1 Konsep Manajemen: Fungsi POAC, Tingkatan & Bidang","kind":"pg","stem":"Keterampilan manajerial yang paling dominan dibutuhkan oleh jajaran Direksi (Top Management) dalam merumuskan visi strategis perusahaan adalah…","options":["keterampilan konseptual (conceptual skills)","keterampilan mengetik laporan harian","keterampilan mengoperasikan mesin produksi","keterampilan teknis (technical skills)"],"key":[0],"why":"Top management membutuhkan keterampilan konseptual tertinggi untuk melihat organisasi secara menyeluruh dan merancang strategi jangka panjang.","src":"kuis"},{"id":"4.0.2","topic":"Badan Usaha & Internasional","sub":"5.1 Konsep Manajemen: Fungsi POAC, Tingkatan & Bidang","kind":"pg","stem":"Penentuan desain kemasan produk, penetapan harga jual, pemilihan saluran distribusi, dan kampanye iklan di media sosial (4P) merupakan ruang lingkup bidang…","options":["Manajemen Administrasi","Manajemen Produksi","Manajemen Pemasaran","Manajemen Keuangan"],"key":[2],"why":"Bauran pemasaran (Marketing Mix 4P: Product, Price, Place, Promotion) adalah inti dari Manajemen Pemasaran.","src":"kuis"},{"id":"4.1.0","topic":"Badan Usaha & Internasional","sub":"5.2 Badan Usaha dalam Perekonomian: BUMN, BUMD & BUMS","kind":"pg","stem":"Perbedaan utama antara BUMN berbentuk Persero dan BUMN berbentuk Perum adalah…","options":["Perum dipimpin oleh RUPS, Persero dipimpin oleh Menteri","Persero modalnya terbagi atas saham (negara minimal 51%) dan mengejar laba, sedangkan Perum modalnya 100% milik negara (tidak terbagi atas saham) dan mengutamakan pelayanan umum","Persero tidak boleh mencari keuntungan","Persero dimiliki swasta penuh, Perum dimiliki daerah"],"key":[1],"why":"Persero berbentuk PT dengan modal saham (minimal 51% milik negara) berorientasi laba & daya saing; Perum modalnya 100% negara untuk kemanfaatan umum.","src":"kuis"},{"id":"4.1.1","topic":"Badan Usaha & Internasional","sub":"5.2 Badan Usaha dalam Perekonomian: BUMN, BUMD & BUMS","kind":"pg","stem":"Dalam Persekutuan Komanditer (CV), sekutu yang hanya menyetorkan modal, tidak ikut memimpin perusahaan, dan tanggung jawabnya terbatas pada modal yang disetor disebut…","options":["sekutu aktif / komplementer","direktur utama","sekutu pasif / komanditer","dewan komisaris"],"key":[2],"why":"Sekutu pasif (sleeping partner / komanditer) hanya menyetor modal dan tanggung jawabnya terbatas sebesar modal yang disetor.","src":"kuis"},{"id":"4.1.2","topic":"Badan Usaha & Internasional","sub":"5.2 Badan Usaha dalam Perekonomian: BUMN, BUMD & BUMS","kind":"pg","stem":"Kekuasaan tertinggi dalam Perseroan Terbatas (PT) yang berwenang mengangkat direksi dan memutuskan pembagian dividen berada pada…","options":["Kementerian Perdagangan","Dewan Komisaris","Direktur Utama","Rapat Umum Pemegang Saham (RUPS)"],"key":[3],"why":"RUPS adalah organ PT yang memegang kekuasaan tertinggi.","src":"kuis"},{"id":"4.2.0","topic":"Badan Usaha & Internasional","sub":"5.3 Koperasi & Perhitungan Sisa Hasil Usaha (SHU)","kind":"pg","stem":"Pemegang kekuasaan tertinggi dalam struktur organisasi koperasi di Indonesia adalah…","options":["Rapat Anggota","Badan Pengawas Koperasi","Anggota dengan simpanan terbesar","Ketua Pengurus Koperasi"],"key":[0],"why":"Menurut UU No. 25 Tahun 1992, Rapat Anggota merupakan pemegang kekuasaan tertinggi dalam koperasi (satu anggota satu suara).","src":"kuis"},{"id":"4.2.1","topic":"Badan Usaha & Internasional","sub":"5.3 Koperasi & Perhitungan Sisa Hasil Usaha (SHU)","kind":"pg","stem":"Simpanan anggota koperasi yang dibayarkan satu kali saat pertama kali masuk menjadi anggota dengan jumlah yang sama untuk setiap anggota disebut…","options":["simpanan sukarela","simpanan pokok","simpanan wajib","dana cadangan"],"key":[1],"why":"Simpanan pokok dibayar sekali saat mendaftar sebagai anggota; simpanan wajib dibayar rutin setiap periode (misal bulanan).","src":"kuis"},{"id":"4.2.2","topic":"Badan Usaha & Internasional","sub":"5.3 Koperasi & Perhitungan Sisa Hasil Usaha (SHU)","kind":"pg","stem":"Mengapa Simpanan Sukarela tidak diikutsertakan dalam perhitungan Jasa Modal saat pembagian SHU koperasi?","options":["Karena simpanan sukarela bersifat seperti tabungan biasa yang dapat ditarik sewaktu-waktu dan bukan modal tetap koperasi","Karena dilarang oleh undang-undang","Karena nilainya selalu lebih kecil dari simpanan pokok","Karena simpanan sukarela adalah milik pemerintah"],"key":[0],"why":"Simpanan sukarela bukan modal sendiri koperasi karena bisa diambil kapan saja; yang dihitung untuk Jasa Modal hanyalah Simpanan Pokok + Simpanan Wajib.","src":"kuis"},{"id":"4.3.0","topic":"Badan Usaha & Internasional","sub":"5.4 Kerja Sama Ekonomi Internasional","kind":"pg","stem":"Organisasi kerja sama ekonomi internasional yang bertujuan mengatur perdagangan bebas dunia dan menyelesaikan sengketa dagang antarnegara adalah…","options":["IMF (International Monetary Fund)","WTO (World Trade Organization)","IBRD / World Bank","ILO (International Labour Organization)"],"key":[1],"why":"WTO adalah organisasi multilateral yang mengatur regulasi perdagangan internasional dan penyelesaian sengketa tarif/non-tarif.","src":"kuis"},{"id":"4.3.1","topic":"Badan Usaha & Internasional","sub":"5.4 Kerja Sama Ekonomi Internasional","kind":"pg","stem":"Mengapa OPEC (Organization of the Petroleum Exporting Countries) dikategorikan sebagai kerja sama multilateral, bukan regional?","options":["Karena hanya mengurus perdagangan beras di Asia","Karena dipimpin oleh Bank Dunia","Karena anggotanya terdiri atas negara-negara penghasil minyak dari berbagai benua/kawasan berbeda (Timur Tengah, Afrika, Amerika Selatan)","Karena anggotanya hanya dua negara"],"key":[2],"why":"Kerja sama regional dibatasi oleh satu kawasan geografis, sedangkan anggota OPEC tersebar lintas benua dengan kesamaan komoditas minyak bumi.","src":"kuis"},{"id":"4.3.2","topic":"Badan Usaha & Internasional","sub":"5.4 Kerja Sama Ekonomi Internasional","kind":"pg","stem":"Kemitraan Ekonomi Komprehensif antara Indonesia dan Australia (IA-CEPA) merupakan contoh kerja sama ekonomi…","options":["antarregional","multilateral","regional","bilateral"],"key":[3],"why":"Kerja sama yang melibatkan tepat dua negara (Indonesia dan Australia) disebut kerja sama bilateral.","src":"kuis"},{"id":"4.4.0","topic":"Badan Usaha & Internasional","sub":"5.5 Perdagangan Internasional: Teori & Kebijakan Proteksi","kind":"pg","stem":"Kebijakan suatu negara menjual barang di pasar luar negeri dengan harga jauh lebih murah dibandingkan harga jual di dalam negerinya sendiri untuk menguasai pasar disebut…","options":["embargo ekonomi","politik dumping","tarif bea masuk","kuota impor"],"key":[1],"why":"Politik dumping adalah diskriminasi harga internasional dengan menjual lebih murah di luar negeri daripada di pasar domestik.","src":"kuis"},{"id":"4.4.1","topic":"Badan Usaha & Internasional","sub":"5.5 Perdagangan Internasional: Teori & Kebijakan Proteksi","kind":"pg","stem":"Selama triwulan I, ekspor komoditas mentah Indonesia turun 15% sementara impor barang konsumsi naik 10% sehingga neraca perdagangan defisit US$1,2 miliar. Strategi struktural paling tepat adalah…","options":["menghentikan seluruh impor barang modal dan bahan baku pabrik","meningkatkan hilirisasi dan ekspor produk manufaktur bernilai tambah tinggi serta mengurangi ketergantungan ekspor komoditas mentah","menaikkan pajak bagi eksportir","menurunkan suku bunga agar masyarakat makin konsumtif membeli barang impor"],"key":[1],"why":"Hilirisasi dan ekspor produk manufaktur meningkatkan nilai tambah devisa dan daya tahan terhadap fluktuasi harga komoditas mentah.","src":"kuis"},{"id":"4.4.2","topic":"Badan Usaha & Internasional","sub":"5.5 Perdagangan Internasional: Teori & Kebijakan Proteksi","kind":"pg","stem":"Manakah di antara berikut ini yang BUKAN merupakan hambatan perdagangan internasional?","options":["Rendahnya standar mutu produk lokal dibanding standar internasional","Proteksi tarif bea masuk yang tinggi oleh negara mitra","Kesepakatan kawasan perdagangan bebas (Free Trade Agreement)","Pembatasan kuota impor"],"key":[2],"why":"Kesepakatan perdagangan bebas (FTA) justru menghapus hambatan tarif dan non-tarif untuk memperlancar arus perdagangan.","src":"kuis"},{"id":"4.5.0","topic":"Badan Usaha & Internasional","sub":"5.6 Kurs Valuta Asing, Devisa & Neraca Pembayaran","kind":"pg","stem":"Seorang eksportir mebel di Jepara menerima pembayaran dari pembeli di Eropa sebesar US$10.000. Ketika ia menukarkan dolar tersebut menjadi Rupiah di bank dalam negeri (Kurs Beli Rp15.700; Kurs Tengah Rp15.800; Kurs Jual Rp15.900), jumlah Rupiah yang diterimanya adalah…","options":["Rp160.000.000","Rp158.000.000","Rp157.000.000","Rp159.000.000"],"key":[2],"why":"Eksportir menjual dolar kepada bank, artinya bank MEMBELI valas tersebut → gunakan Kurs Beli: 10.000 × Rp15.700 = Rp157.000.000.","src":"kuis"},{"id":"4.5.1","topic":"Badan Usaha & Internasional","sub":"5.6 Kurs Valuta Asing, Devisa & Neraca Pembayaran","kind":"pg","stem":"Apabila nilai tukar bergerak dari US$1 = Rp15.500 menjadi US$1 = Rp16.400 karena mekanisme pasar, maka dampak langsungnya terhadap perdagangan luar negeri Indonesia adalah…","options":["Rupiah mengalami depresiasi sehingga harga barang ekspor Indonesia menjadi lebih kompetitif (murah) bagi pembeli asing","Rupiah mengalami apresiasi sehingga barang impor menjadi lebih murah","impor barang mewah melonjak tajam","neraca perdagangan otomatis langsung defisit"],"key":[0],"why":"Butuh lebih banyak Rupiah per US$1 berarti Rupiah terdepresiasi (melemah); hal ini membuat barang Indonesia relatif lebih murah dalam dolar sehingga mendorong ekspor.","src":"kuis"},{"id":"4.5.2","topic":"Badan Usaha & Internasional","sub":"5.6 Kurs Valuta Asing, Devisa & Neraca Pembayaran","kind":"pg","stem":"Jika nilai ekspor barang suatu negara lebih besar daripada nilai impor barangnya (X > M), maka neraca perdagangannya mengalami…","options":["surplus","ekuilibrium nol","devaluasi","defisit"],"key":[0],"why":"Neraca perdagangan = Ekspor barang − Impor barang. Jika X > M maka neraca perdagangan surplus.","src":"kuis"},{"id":"5.0.0","topic":"Akuntansi Keuangan Dasar","sub":"6.1 Konsep Dasar Akuntansi, Pemakai Informasi & Klasifikasi Akun","kind":"pg","stem":"Pihak eksternal yang membutuhkan laporan keuangan perusahaan terutama untuk menilai kemampuan perusahaan dalam membayar pokok pinjaman dan bunganya tepat waktu adalah…","options":["pelanggan eceran","manajer pemasaran","serikat pekerja","kreditor / pihak perbankan"],"key":[3],"why":"Kreditor (bank/pemberi pinjaman) menganalisis likuiditas dan solvabilitas perusahaan untuk memastikan pinjaman dapat dilunasi.","src":"kuis"},{"id":"5.0.1","topic":"Akuntansi Keuangan Dasar","sub":"6.1 Konsep Dasar Akuntansi, Pemakai Informasi & Klasifikasi Akun","kind":"pg","stem":"Manakah pasangan akun berikut yang keduanya termasuk ke dalam kelompok Aset Lancar (Current Assets)?","options":["Sewa Dibayar di Muka dan Utang Usaha","Kas dan Peralatan Kantor","Piutang Usaha dan Perlengkapan","Kendaraan dan Gedung"],"key":[2],"why":"Piutang Usaha dan Perlengkapan sama-sama merupakan Aset Lancar; Peralatan, Kendaraan, dan Gedung adalah Aset Tetap.","src":"kuis"},{"id":"5.0.2","topic":"Akuntansi Keuangan Dasar","sub":"6.1 Konsep Dasar Akuntansi, Pemakai Informasi & Klasifikasi Akun","kind":"pg","stem":"Akun 'Pendapatan Jasa Diterima di Muka' dalam laporan posisi keuangan (neraca) dikelompokkan sebagai…","options":["Pendapatan Operasional","Aset Lancar","Liabilitas Jangka Pendek (Utang Jasa)","Ekuitas Pemilik"],"key":[2],"why":"Karena uang sudah diterima tetapi jasa belum diberikan kepada pelanggan, perusahaan memiliki kewajiban (utang) untuk menyelesaikan jasa tersebut.","src":"kuis"},{"id":"5.1.0","topic":"Akuntansi Keuangan Dasar","sub":"6.2 Persamaan Dasar Akuntansi (PDA) & Analisis Transaksi","kind":"pg","stem":"Manakah di antara transaksi berikut yang secara langsung MEMENGARUHI komponen Ekuitas (Modal) dalam Persamaan Dasar Akuntansi?","options":["Membayar beban listrik dan telepon bulan berjalan sebesar Rp2.000.000","Melunasi utang usaha kepada pemasok sebesar Rp8.000.000","Menerima pelunasan piutang dari pelanggan sebesar Rp5.000.000","Membeli peralatan kantor secara kredit senilai Rp15.000.000"],"key":[0],"why":"Ekuitas hanya dipengaruhi oleh 4 hal: setoran modal, pendapatan, beban, dan prive. Membayar beban listrik mengurangi Kas (−Aset) dan mengurangi Ekuitas.","src":"kuis"},{"id":"5.1.1","topic":"Akuntansi Keuangan Dasar","sub":"6.2 Persamaan Dasar Akuntansi (PDA) & Analisis Transaksi","kind":"pg","stem":"Jika perusahaan membeli kendaraan operasional seharga Rp150.000.000 dengan membayar uang muka tunai Rp50.000.000 dan sisanya secara kredit, maka pengaruhnya pada persamaan dasar akuntansi adalah…","options":["Aset bertambah Rp150 juta dan Ekuitas bertambah Rp150 juta","Ekuitas berkurang Rp50 juta","Aset berkurang Rp50 juta dan Liabilitas bertambah Rp100 juta","Aset bersih bertambah Rp100 juta (Kendaraan +150 juta, Kas −50 juta) dan Liabilitas (Utang) bertambah Rp100 juta"],"key":[3],"why":"Kendaraan (+150 jt) dan Kas (−50 jt) menghasilkan kenaikan bersih Aset +Rp100 juta, diimbangi kenaikan Utang (+Liabilitas) Rp100 juta.","src":"kuis"},{"id":"5.1.2","topic":"Akuntansi Keuangan Dasar","sub":"6.2 Persamaan Dasar Akuntansi (PDA) & Analisis Transaksi","kind":"pg","stem":"Diketahui total Aset perusahaan Rp240.000.000 dan total Liabilitasnya Rp90.000.000. Berapakah besarnya Ekuitas pemilik?","options":["Rp150.000.000","Rp330.000.000","Rp90.000.000","Rp240.000.000"],"key":[0],"why":"Aset = Liabilitas + Ekuitas → Ekuitas = Rp240.000.000 − Rp90.000.000 = Rp150.000.000.","src":"kuis"},{"id":"5.2.0","topic":"Akuntansi Keuangan Dasar","sub":"6.3 Mekanisme Debit–Kredit, Saldo Normal & Jurnal Umum","kind":"pg","stem":"Kelompok akun yang memiliki saldo normal di sisi DEBIT dan bertambah di sisi DEBIT adalah…","options":["Harta, Utang, dan Modal","Utang, Modal, dan Pendapatan","Harta, Beban, dan Prive","Pendapatan, Beban, dan Prive"],"key":[2],"why":"Ingat jembatan keledai H–B–P (Harta, Beban, Prive): ketiganya bersaldo normal Debit dan bertambah di Debit.","src":"kuis"},{"id":"5.2.1","topic":"Akuntansi Keuangan Dasar","sub":"6.3 Mekanisme Debit–Kredit, Saldo Normal & Jurnal Umum","kind":"pg","stem":"Pemilik mengambil uang tunai perusahaan sebesar Rp1.500.000 untuk keperluan pribadi (Prive). Jurnal umum yang tepat adalah…","options":["(D) Beban Gaji Rp1.500.000 / (K) Kas Rp1.500.000","(D) Prive Rp1.500.000 / (K) Kas Rp1.500.000","(D) Kas Rp1.500.000 / (K) Prive Rp1.500.000","(D) Modal Rp1.500.000 / (K) Prive Rp1.500.000"],"key":[1],"why":"Prive bertambah di Debit (Rp1.500.000) dan Kas berkurang di Kredit (Rp1.500.000).","src":"kuis"},{"id":"5.2.2","topic":"Akuntansi Keuangan Dasar","sub":"6.3 Mekanisme Debit–Kredit, Saldo Normal & Jurnal Umum","kind":"pg","stem":"Bukti transaksi pembelian atau penjualan barang/jasa yang dilakukan secara KREDIT disebut…","options":["cek","nota kontan","kuitansi","faktur (invoice)"],"key":[3],"why":"Faktur adalah bukti transaksi kredit; nota kontan adalah bukti pembelian/penjualan tunai; kuitansi adalah bukti penerimaan uang.","src":"kuis"},{"id":"5.3.0","topic":"Akuntansi Keuangan Dasar","sub":"6.4 Buku Besar, Neraca Saldo & Jurnal Penyesuaian (AJP)","kind":"pg","stem":"Di Neraca Saldo tercatat akun Perlengkapan Rp6.000.000. Pada akhir periode, perlengkapan yang masih tersisa sebesar Rp2.000.000. Jurnal penyesuaian yang benar adalah…","options":["(D) Beban Perlengkapan Rp6.000.000 / (K) Kas Rp6.000.000","(D) Perlengkapan Rp4.000.000 / (K) Beban Perlengkapan Rp4.000.000","(D) Beban Perlengkapan Rp2.000.000 / (K) Perlengkapan Rp2.000.000","(D) Beban Perlengkapan Rp4.000.000 / (K) Perlengkapan Rp4.000.000"],"key":[3],"why":"AJP perlengkapan mencatat jumlah yang TERPAKAI: Rp6.000.000 − Rp2.000.000 = Rp4.000.000.","src":"kuis"},{"id":"5.3.1","topic":"Akuntansi Keuangan Dasar","sub":"6.4 Buku Besar, Neraca Saldo & Jurnal Penyesuaian (AJP)","kind":"pg","stem":"Jika pada saat membayar sewa 1 tahun (1 Oktober 2025 sebesar Rp24.000.000) perusahaan mencatatnya di Neraca Saldo sebagai 'Beban Sewa' (Pendekatan Beban), maka AJP pada 31 Desember 2025 adalah…","options":["(D) Beban Sewa Rp6.000.000 / (K) Sewa Dibayar di Muka Rp6.000.000","(D) Sewa Dibayar di Muka Rp6.000.000 / (K) Beban Sewa Rp6.000.000","(D) Beban Sewa Rp18.000.000 / (K) Kas Rp18.000.000","(D) Sewa Dibayar di Muka Rp18.000.000 / (K) Beban Sewa Rp18.000.000"],"key":[3],"why":"Pendekatan Beban mencatat bagian yang BELUM terpakai (9 bulan tahun depan: 9/12 × Rp24 juta = Rp18 juta) dengan mendebit Sewa Dibayar di Muka dan mengkredit Beban Sewa.","src":"kuis"},{"id":"5.3.2","topic":"Akuntansi Keuangan Dasar","sub":"6.4 Buku Besar, Neraca Saldo & Jurnal Penyesuaian (AJP)","kind":"pg","stem":"Jurnal penyesuaian untuk mencatat penyusutan peralatan kantor sebesar Rp2.500.000 adalah…","options":["(D) Akumulasi Penyusutan Peralatan Rp2.500.000 / (K) Beban Penyusutan Rp2.500.000","(D) Beban Peralatan Rp2.500.000 / (K) Kas Rp2.500.000","(D) Beban Penyusutan Peralatan Rp2.500.000 / (K) Akumulasi Penyusutan Peralatan Rp2.500.000","(D) Beban Penyusutan Peralatan Rp2.500.000 / (K) Peralatan Rp2.500.000"],"key":[2],"why":"Penyusutan aset tetap selalu mengkredit akun kontra 'Akumulasi Penyusutan', bukan langsung mengurangi akun Peralatan.","src":"kuis"},{"id":"5.4.0","topic":"Akuntansi Keuangan Dasar","sub":"6.5 Kertas Kerja (Worksheet) & Laporan Keuangan","kind":"pg","stem":"Jika diketahui Modal Awal Rp50.000.000, Modal Akhir Rp72.000.000, Prive Rp8.000.000, dan Total Beban Rp15.000.000, berapakah Total Pendapatan perusahaan pada periode tersebut?","options":["Rp37.000.000","Rp45.000.000","Rp53.000.000","Rp30.000.000"],"key":[1],"why":"Modal Akhir = Modal Awal + Laba − Prive → 72 = 50 + Laba − 8 → Laba Bersih = Rp30 juta. Karena Laba = Pendapatan − Beban, maka Pendapatan = 30 + 15 = Rp45.000.000.","src":"kuis"},{"id":"5.4.1","topic":"Akuntansi Keuangan Dasar","sub":"6.5 Kertas Kerja (Worksheet) & Laporan Keuangan","kind":"pg","stem":"Dalam Kertas Kerja (Worksheet) 10 kolom, akun-akun yang dipindahkan ke kolom Laba Rugi hanyalah…","options":["Seluruh akun Aset dan Liabilitas","Modal, Prive, dan Laba Bersih","Kas, Piutang, dan Utang","Pendapatan dan Beban (Akun Nominal)"],"key":[3],"why":"Kolom Laba Rugi pada Kertas Kerja hanya menampung akun nominal (Pendapatan di Kredit, Beban di Debit).","src":"kuis"},{"id":"5.4.2","topic":"Akuntansi Keuangan Dasar","sub":"6.5 Kertas Kerja (Worksheet) & Laporan Keuangan","kind":"pg","stem":"Urutan penyusunan laporan keuangan yang benar karena saling berkaitan adalah…","options":["Neraca → Laporan Laba Rugi → Laporan Perubahan Ekuitas","Laporan Perubahan Ekuitas → Neraca → Laporan Laba Rugi","Laporan Laba Rugi → Laporan Perubahan Ekuitas → Neraca (Laporan Posisi Keuangan)","Jurnal Penutup → Laporan Laba Rugi → Neraca"],"key":[2],"why":"Laba Bersih dari Laporan Laba Rugi diperlukan untuk menghitung Modal Akhir di Laporan Perubahan Ekuitas, dan Modal Akhir diperlukan untuk menyusun Neraca.","src":"kuis"},{"id":"5.5.0","topic":"Akuntansi Keuangan Dasar","sub":"6.6 Jurnal Penutup, Neraca Saldo Setelah Penutupan & Akuntansi Dagang Dasar","kind":"pg","stem":"Jurnal penutup yang benar untuk menutup akun Pendapatan Jasa sebesar Rp40.000.000 pada akhir periode adalah…","options":["(D) Ikhtisar Laba Rugi Rp40.000.000 / (K) Pendapatan Jasa Rp40.000.000","(D) Kas Rp40.000.000 / (K) Pendapatan Jasa Rp40.000.000","(D) Pendapatan Jasa Rp40.000.000 / (K) Ikhtisar Laba Rugi Rp40.000.000","(D) Pendapatan Jasa Rp40.000.000 / (K) Modal Rp40.000.000"],"key":[2],"why":"Pendapatan bersaldo normal Kredit; untuk mengenolkannya pada jurnal penutup, Pendapatan didebit dan Ikhtisar Laba Rugi dikredit.","src":"kuis"},{"id":"5.5.1","topic":"Akuntansi Keuangan Dasar","sub":"6.6 Jurnal Penutup, Neraca Saldo Setelah Penutupan & Akuntansi Dagang Dasar","kind":"pg","stem":"Akun manakah yang MASIH TERCANTUM di dalam Neraca Saldo Setelah Penutupan (NSSP)?","options":["Kas, Piutang Usaha, Peralatan, Utang Usaha, dan Modal Akhir (Akun Riil)","Beban Perlengkapan dan Beban Penyusutan","Prive dan Ikhtisar Laba Rugi","Pendapatan Jasa dan Beban Gaji"],"key":[0],"why":"Setelah jurnal penutup diposting, seluruh akun nominal dan prive bersaldo nol, sehingga NSSP hanya berisi akun riil (Aset, Liabilitas, dan Modal Akhir).","src":"kuis"},{"id":"5.5.2","topic":"Akuntansi Keuangan Dasar","sub":"6.6 Jurnal Penutup, Neraca Saldo Setelah Penutupan & Akuntansi Dagang Dasar","kind":"pg","stem":"Pembelian barang dagang dengan syarat pembayaran '2/10, n/30' memiliki arti…","options":["pembeli wajib membayar denda 2% setelah 10 hari","barang dikirim dalam 10 sampai 30 hari","pembeli mendapat diskon 10% jika membayar dalam 2 hari","pembeli mendapat potongan harga 2% jika melunasi dalam waktu maksimal 10 hari sejak tanggal transaksi, dengan batas jatuh tempo pelunasan 30 hari"],"key":[3],"why":"Syarat 2/10, n/30 berarti diskon 2% bila dilunasi ≤10 hari sejak tanggal faktur, dan jatuh tempo pelunasan penuh paling lambat 30 hari.","src":"kuis"},{"id":"hots-h1","topic":"Konsep Dasar Ekonomi","sub":"HOTS · Ekspansi Industri & Biaya Sosial (Model Pusmendik #1)","kind":"pg","title":"Ekspansi Industri & Biaya Sosial (Model Pusmendik #1)","stem":"Sebuah kota kecil berkembang pesat akibat tumbuhnya industri manufaktur: penyerapan tenaga kerja dan daya beli perdagangan meningkat, namun kemacetan, polusi, serta harga tanah/hunian ikut melonjak. Kesimpulan analitis manakah yang paling tepat?","options":["Perkembangan ekonomi selalu meningkatkan kesejahteraan tanpa menimbulkan biaya sosial","Peningkatan aktivitas ekonomi menciptakan lapangan kerja sekaligus tantangan eksternalitas yang harus dikelola lewat kebijakan tata ruang dan lingkungan","Daya beli masyarakat pasti turun drastis karena tumbuhnya sektor perdagangan","Kegiatan industri harus dihentikan seluruhnya karena memicu kemacetan dan kenaikan harga tanah"],"key":[1],"why":"Sesuai soal resmi TKA Pusmendik: pertumbuhan industri membawa dampak positif (lapangan kerja & daya beli) sekaligus eksternalitas negatif (polusi & harga hunian) yang harus dikelola dengan kebijakan publik yang tepat, bukan dihentikan.","src":"hots"},{"id":"hots-h2","topic":"Konsep Dasar Ekonomi","sub":"HOTS · Keputusan Bisnis & Laba Ekonomi","kind":"pg","title":"Keputusan Bisnis & Laba Ekonomi","stem":"Dokter Dina yang semula bekerja di rumah sakit dengan gaji Rp15.000.000/bulan memutuskan resign untuk membuka klinik sendiri di ruko miliknya (yang jika disewakan ke orang lain laku Rp5.000.000/bulan). Pendapatan klinik Rp45.000.000/bulan dengan biaya obat, listrik, dan gaji perawat Rp22.000.000/bulan. Berapa Laba Ekonomi klinik Dokter Dina?","options":["−Rp2.000.000/bulan","Rp23.000.000/bulan","Rp3.000.000/bulan","Rp8.000.000/bulan"],"key":[2],"why":"Laba Akuntansi = 45 juta − 22 juta (biaya eksplisit) = Rp23 juta. Biaya implisit (biaya peluang) mencakup gaji dokter yang dilepas (Rp15 juta) + sewa ruko milik sendiri yang dikorbankan (Rp5 juta) = Rp20 juta. Maka Laba Ekonomi = 23 juta − 20 juta = Rp3.000.000/bulan.","src":"hots"},{"id":"hots-h3","topic":"Ekonomi Mikro & Pasar","sub":"HOTS · Keseimbangan Pasar Tomat (Model Pusmendik #3)","kind":"pg","title":"Keseimbangan Pasar Tomat (Model Pusmendik #3)","stem":"Daftar harga tomat di Pasar Kota B: saat harga Rp9.000/kg, jumlah permintaan 800 kg dan penawaran 1.000 kg. Saat harga naik menjadi Rp10.000/kg, permintaan turun menjadi 600 kg dan penawaran naik menjadi 1.200 kg. Titik keseimbangan pasar (Qe ; Pe) adalah…","options":["600 kg ; Rp10.000","800 kg ; Rp9.000","1.000 kg ; Rp8.000","900 kg ; Rp8.500"],"key":[3],"why":"Setiap penurunan harga Rp1.000 menaikkan Qd sebesar 200 kg (Qd = 2.600 − 0,2P) dan menurunkan Qs sebesar 200 kg (Qs = −800 + 0,2P). Saat Qd = Qs: 2.600 − 0,2P = −800 + 0,2P → 3.400 = 0,4P → Pe = Rp8.500 dan Qe = 900 kg.","src":"hots"},{"id":"hots-h4","topic":"Ekonomi Mikro & Pasar","sub":"HOTS · Pergeseran Ganda Permintaan & Penawaran","kind":"pg","title":"Pergeseran Ganda Permintaan & Penawaran","stem":"Menjelang tahun ajaran baru, permintaan buku tulis meningkat tajam sementara pada saat yang sama harga bubur kertas (bahan baku buku) dunia turun drastis berkat teknologi daur ulang baru. Apa yang pasti terjadi pada keseimbangan pasar buku tulis?","options":["Baik harga maupun kuantitas keseimbangan tidak berubah","Harga keseimbangan pasti naik, kuantitas belum tentu","Kuantitas keseimbangan (Qe) pasti meningkat, sedangkan perubahan harga (Pe) bergantung pada besaran pergeseran D dan S","Kuantitas keseimbangan pasti turun drastis"],"key":[2],"why":"Permintaan naik (kurva D geser ke kanan: Q↑, P↑) dan penawaran naik karena biaya bahan baku turun (kurva S geser ke kanan: Q↑, P↓). Kedua pergeseran sama-sama mendorong kuantitas (Qe) NAIK, sedangkan harga (Pe) tergantung mana yang bergeser lebih besar.","src":"hots"},{"id":"hots-h5","topic":"Makro: PDB & Tenaga Kerja","sub":"HOTS · Perbandingan Pendapatan Per Kapita (Model Pusmendik #4)","kind":"pg","title":"Perbandingan Pendapatan Per Kapita (Model Pusmendik #4)","stem":"Tahun 2023: Negara Astina memiliki Pendapatan Nasional Rp283.300 miliar (penduduk 51 juta); Negara Alengka Rp326.600 miliar (penduduk 31 juta); Negara Amarta Rp917.700 miliar (penduduk 255,5 juta). Kesimpulan yang tepat adalah…","options":["Negara Alengka memiliki pendapatan per kapita tertinggi (≈Rp10,54 juta), disusul Negara Astina (≈Rp5,55 juta), dan Negara Amarta (≈Rp3,59 juta)","Pendapatan per kapita ketiga negara sama besar","Urutan pendapatan per kapita tertinggi adalah Astina, Alengka, lalu Amarta","Negara Amarta memiliki pendapatan per kapita tertinggi karena pendapatan nasionalnya paling besar"],"key":[0],"why":"IPC Alengka = 326.600/31 ≈ Rp10,54 juta; IPC Astina = 283.300/51 ≈ Rp5,55 juta; IPC Amarta = 917.700/255,5 ≈ Rp3,59 juta. Meskipun PDB total Amarta terbesar, penduduknya sangat banyak sehingga IPC-nya terendah.","src":"hots"},{"id":"hots-h6","topic":"Makro: PDB & Tenaga Kerja","sub":"HOTS · Efek Angka Pengganda (Multiplier) Investasi","kind":"pg","title":"Efek Angka Pengganda (Multiplier) Investasi","stem":"Dalam suatu perekonomian diketahui fungsi tabungan S = −100 + 0,2Y (dalam triliun rupiah) dan investasi awal I = Rp60 triliun. Jika investasi swasta meningkat menjadi Rp100 triliun, maka pendapatan nasional keseimbangan akan berubah dari…","options":["Rp1.000 triliun menjadi Rp1.200 triliun","Rp500 triliun menjadi Rp540 triliun (naik Rp40 triliun)","Rp800 triliun menjadi Rp1.000 triliun (naik Rp200 triliun)","Rp600 triliun menjadi Rp800 triliun"],"key":[2],"why":"Keseimbangan awal (S = I): −100 + 0,2Y = 60 → 0,2Y = 160 → Y₁ = Rp800 triliun. Angka pengganda k = 1/MPS = 1/0,2 = 5. Tambahan investasi ΔI = 100 − 60 = Rp40 triliun menghasilkan ΔY = 5 × 40 = Rp200 triliun, sehingga Y₂ = Rp1.000 triliun.","src":"hots"},{"id":"hots-h7","topic":"Inflasi, Moneter & Fiskal","sub":"HOTS · Analisis Tren Laju Inflasi IHK (Model Pusmendik #17)","kind":"pg","title":"Analisis Tren Laju Inflasi IHK (Model Pusmendik #17)","stem":"BPS mencatat IHK suatu wilayah sebesar 112 pada tahun 2022, meningkat menjadi 118 pada tahun 2023, dan menjadi 125 pada tahun 2024. Pernyataan yang tepat mengenai perkembangan laju inflasi wilayah tersebut adalah…","options":["Inflasi tahun 2023 dan 2024 menunjukkan tren penurunan","Laju inflasi tahun 2024 (5,93%) lebih tinggi dibandingkan tahun 2023 (5,36%)","Laju inflasi tahun 2023 (5,36%) lebih tinggi daripada tahun 2024 (5,00%)","Laju inflasi tahun 2023 mencapai tepat 6,00% dan tahun 2024 tepat 7,00%"],"key":[1],"why":"Inflasi 2023 = ((118 − 112)/112) × 100% = 5,36%. Inflasi 2024 = ((125 − 118)/118) × 100% = 5,93%. Jadi inflasi tahun 2024 lebih tinggi dibandingkan tahun 2023.","src":"hots"},{"id":"hots-h8","topic":"Inflasi, Moneter & Fiskal","sub":"HOTS · Sinkronisasi Kebijakan Moneter & Fiskal","kind":"pg","title":"Sinkronisasi Kebijakan Moneter & Fiskal","stem":"Ketika suatu negara menghadapi stagflasi ringan yang didominasi lonjakan inflasi permintaan serta pelemahan kurs mata uang, kombinasi kebijakan moneter dan fiskal kontraktif yang selaras untuk meredam gejolak harga adalah…","options":["BI membeli SBN dan Pemerintah mencetak uang baru","BI menaikkan BI-Rate & menjual SBN di pasar terbuka, sedangkan Pemerintah mengefisienkan belanja & mengoptimalkan penerimaan pajak","BI menurunkan BI-Rate dan Pemerintah menaikkan belanja infrastruktur","BI menurunkan GWM dan Pemerintah memberikan pemotongan pajak konsumsi"],"key":[1],"why":"Moneter kontraktif (naikkan BI-Rate, jual SBN, naikkan GWM) dan fiskal kontraktif (tahan belanja non-prioritas, optimalkan pajak) bekerja searah mengerem kelebihan permintaan agregat dan menjaga stabilitas nilai tukar.","src":"hots"},{"id":"hots-h9","topic":"Badan Usaha & Internasional","sub":"HOTS · SHU Koperasi & Perdagangan Internasional","kind":"pg","title":"SHU Koperasi & Perdagangan Internasional","stem":"Koperasi Mandiri membukukan SHU Rp60.000.000 (alokasi Jasa Modal 20% dan Jasa Usaha 30%). Total simpanan pokok+wajib koperasi Rp80.000.000 dan total penjualan koperasi Rp150.000.000. Pak Budi memiliki simpanan pokok+wajib Rp4.000.000, simpanan sukarela Rp6.000.000, dan belanja di koperasi Rp15.000.000. Berapa SHU yang diterima Pak Budi?","options":["Rp600.000","Rp1.800.000","Rp3.300.000","Rp2.400.000"],"key":[3],"why":"Abaikan simpanan sukarela! Jasa Modal = (4 juta / 80 juta) × (20% × 60 juta) = 0,05 × 12 juta = Rp600.000. Jasa Usaha = (15 juta / 150 juta) × (30% × 60 juta) = 0,10 × 18 juta = Rp1.800.000. Total SHU Pak Budi = Rp600.000 + Rp1.800.000 = Rp2.400.000.","src":"hots"},{"id":"hots-h10","topic":"Akuntansi Keuangan Dasar","sub":"HOTS · Laporan Keuangan & Persamaan Akuntansi (Model Pusmendik #15)","kind":"pg","title":"Laporan Keuangan & Persamaan Akuntansi (Model Pusmendik #15)","stem":"PT Sejahtera Makmur per 31 Desember memiliki data: Modal Awal Rp120.000.000, Pendapatan Jasa Rp95.000.000, Pendapatan Bunga Rp3.000.000, Beban Gaji Rp18.000.000, Beban Sewa Rp9.000.000, Beban Perlengkapan Rp6.000.000, dan Prive Rp7.000.000. Berapakah Laba Bersih dan Modal Akhir perusahaan?","options":["Laba Bersih Rp58.000.000 dan Modal Akhir Rp178.000.000","Laba Bersih Rp65.000.000 dan Modal Akhir Rp178.000.000","Laba Bersih Rp72.000.000 dan Modal Akhir Rp192.000.000","Laba Bersih Rp65.000.000 dan Modal Akhir Rp185.000.000"],"key":[1],"why":"Total Pendapatan = 95 + 3 = Rp98 juta. Total Beban = 18 + 9 + 6 = Rp33 juta (Prive tidak masuk Laba Rugi!). Laba Bersih = 98 − 33 = Rp65.000.000. Modal Akhir = Modal Awal (120 jt) + Laba Bersih (65 jt) − Prive (7 jt) = Rp178.000.000.","src":"hots"}]};
